namespace sv_c0343fdf3b4b4fd9a0fbc5b01cf74647.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Components subscribe to <see cref="OnWarehouseChanged"/> to react to selection changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
            await OnWarehouseChanged.Invoke();
    }
}

namespace sv_c0343fdf3b4b4fd9a0fbc5b01cf74647.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and broadcasts results to all subscribers.
/// Polling is ref-counted: it runs while at least one component has called <see cref="StartPollingAsync"/>.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _lastAlertCount;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += OnWarehouseChangedAsync;
    }

    public int LastAlertCount => _lastAlertCount;

    /// <summary>
    /// Raised whenever a new alert count is fetched. All subscribed components should
    /// call <c>InvokeAsync(StateHasChanged)</c> inside their handler.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    public async Task StartPollingAsync()
    {
        _subscriberCount++;

        if (_subscriberCount == 1)
        {
            await PollOnceAsync();
            StartTimer();
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
            StopTimer();
    }

    /// <summary>Forces an immediate refresh (e.g. after a warehouse switch).</summary>
    public async Task RefreshAsync()
    {
        await PollOnceAsync();
    }

    private async Task PollOnceAsync()
    {
        _lastAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private void StartTimer()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = RunPollingLoopAsync(_cts.Token);
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
        _timer = null;
        _cts = null;
    }

    private async Task RunPollingLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on stop
        }
    }

    private async Task OnWarehouseChangedAsync()
    {
        if (_subscriberCount > 0)
            await PollOnceAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= OnWarehouseChangedAsync;
        StopTimer();
    }
}

