@using sv_c0343fdf3b4b4fd9a0fbc5b01cf74647.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" style="width: auto;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
            await WarehouseState.SetWarehouseAsync(id);
    }

    private Task HandleWarehouseChanged()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@using sv_c0343fdf3b4b4fd9a0fbc5b01cf74647.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (_alertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@_alertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    private int _alertCount;

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        _alertCount = AlertService.LastAlertCount;
    }

    private Task HandleAlertCountChanged()
    {
        _alertCount = AlertService.LastAlertCount;
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
    }
}

