@using sv_c0343fdf3b4b4fd9a0fbc5b01cf74647.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            @if (_alertCount > 0)
            {
                <span class="badge bg-danger fs-6">@_alertCount items</span>
            }
            else
            {
                <span class="badge bg-success fs-6">None</span>
            }
        </p>
        <p class="text-muted mb-0">
            <small>Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
        </p>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdate = DateTime.Now;

    protected override async Task OnInitializedAsync()
    {
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;

        await AlertService.StartPollingAsync();
        _alertCount = AlertService.LastAlertCount;
    }

    private Task HandleAlertCountChanged()
    {
        _alertCount = AlertService.LastAlertCount;
        _lastUpdate = DateTime.Now;
        return InvokeAsync(StateHasChanged);
    }

    private Task HandleWarehouseChanged()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.StopPolling();
    }
}

